//! The exercise catalog. The public part of each exercise (statement, visible examples, starter
//! code) is data in `exercises/<id>/exercise.json`. The tests are NOT in that file: they are
//! generated by `cases.rs` at check time, and never leave the Rust side.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::error::AppError;

#[derive(Debug, Clone, Copy, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum Difficulty {
    Easy,
    Medium,
    Hard,
}

/// An example shown to the learner next to the statement.
#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct Example {
    pub input: String,
    pub output: String,
}

/// What the front end is allowed to know about an exercise.
#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Exercise {
    pub id: String,
    pub title: String,
    pub difficulty: Difficulty,
    pub summary: String,
    /// Themes the learner can filter on, e.g. "Boucles".
    pub topics: Vec<String>,
    /// What the exercise is about. Markdown.
    pub statement: String,
    /// The format of the input the program receives. Markdown.
    pub input: String,
    /// The format of the output the program must print. Markdown.
    pub output: String,
    /// Traps and hints worth knowing before starting. Markdown.
    #[serde(default)]
    pub notes: Option<String>,
    pub examples: Vec<Example>,
    /// Code shown in the editor, by language id (see `languages.json`).
    pub starters: BTreeMap<String, String>,
}

const SOURCES: [&str; 15] = [
    include_str!("../exercises/fibonacci/exercise.json"),
    include_str!("../exercises/dict_sum/exercise.json"),
    include_str!("../exercises/list_extend/exercise.json"),
    include_str!("../exercises/fizzbuzz/exercise.json"),
    include_str!("../exercises/max_in_list/exercise.json"),
    include_str!("../exercises/count_vowels/exercise.json"),
    include_str!("../exercises/palindrome/exercise.json"),
    include_str!("../exercises/factorial/exercise.json"),
    include_str!("../exercises/reverse_words/exercise.json"),
    include_str!("../exercises/tips/exercise.json"),
    include_str!("../exercises/primes/exercise.json"),
    include_str!("../exercises/word_count/exercise.json"),
    include_str!("../exercises/dedupe/exercise.json"),
    include_str!("../exercises/change_coins/exercise.json"),
    include_str!("../exercises/caesar/exercise.json"),
];

/// Parses the embedded catalog, in display order.
///
/// # Errors
///
/// Returns an error if an `exercise.json` is malformed (guarded by a unit test).
pub fn all() -> Result<Vec<Exercise>, AppError> {
    SOURCES
        .iter()
        .map(|source| serde_json::from_str(source).map_err(AppError::from))
        .collect()
}

/// Finds an exercise by id.
///
/// # Errors
///
/// Returns an error if the catalog is malformed or the id is unknown.
pub fn find(id: &str) -> Result<Exercise, AppError> {
    all()?
        .into_iter()
        .find(|exercise| exercise.id == id)
        .ok_or_else(|| AppError::UnknownExercise(id.to_owned()))
}

/// Lists the exercises.
#[tauri::command]
pub async fn list_exercises() -> Result<Vec<Exercise>, AppError> {
    all()
}
